sys_script_include.script:
var TreinamentoScript = Class.create();
TreinamentoScript.prototype = {
    initialize: function() {
    },

	refQualAgenda: function(){
        var agendasNotToBeShown = [];

        //Verifica os treinamentos em que estou matriculado
        var grEnrollment = new GlideRecord("x_1588982_treina_0_enrollment");
        grEnrollment.addEncodedQuery("studentDYNAMIC90d1921e5f510100a9ad2572f2b477fe^stateIN2,3");
        grEnrollment.query();
        while(grEnrollment.next()){
            agendasNotToBeShown.push(grEnrollment.agenda.sys_id.toString());
        }

        var agendasToBeShown = [];

        //Define quais treinamentos devem ser mostrados
        var grAgenda = new GlideRecord("x_1588982_treina_0_agenda");
        grAgenda.addQuery("available_vacancies", "!=", 0);    // Apenas treinamentos com vagas abertas
        grAgenda.query();
        while(grAgenda.next()){
            var agendaSys_ID = grAgenda.sys_id.toString();

            //Verifica se já possui 3 matrículas
            var gagEnrollment = new GlideAggregate("x_1588982_treina_0_enrollment");
            gagEnrollment.addEncodedQuery("opened_byDYNAMIC90d1921e5f510100a9ad2572f2b477fe^stateIN2,3");
            gagEnrollment.addEncodedQuery("agenda.course=" + grAgenda.course.sys_id.toString());
            gagEnrollment.addQuery("state", "!=", 4);
            gagEnrollment.addAggregate("COUNT");
            gagEnrollment.query();

            var maxEnrolls = false;

            if(gagEnrollment.next() && gagEnrollment.getAggregate("COUNT") >= 3){
                maxEnrolls = true;
            }

            var userID = gs.getUserID(); // Captura usuário atualmente logado

            // Verifica a data dos Treinamentos
            var reachedLimitDate = false;
            var today = new GlideDate();

            var glideAgendaDate = new GlideDate();
            glideAgendaDate.setValue(grAgenda.training_date);

            if(today.compareTo(glideAgendaDate) > 0){
                reachedLimitDate = true;
            }

            //Verifica se eu sou o instrutor, se atingiu o número máximo de inscrições e a data do treinamento.
            if(agendasNotToBeShown.indexOf(agendaSys_ID) == -1 && maxEnrolls == false && grAgenda.instructor.user != userID && reachedLimitDate == false){
                agendasToBeShown.push(agendaSys_ID);
            }
        }

        if(agendasToBeShown.length === 0){
            return "sys_idIN123445";
        } else {
            return "sys_idIN" + agendasToBeShown.join(",");
        }

    },


    type: 'TreinamentoScript'
};
